import java.nio.file.*;import java.util.*;import javax.tools.*;import javax.lang.model.element.*;import javax.lang.model.type.*;import com.sun.source.tree.*;import com.sun.source.util.*;
public class NameScanner {
 public static void main(String[] a)throws Exception{
 JavaCompiler c=ToolProvider.getSystemJavaCompiler();DiagnosticCollector<JavaFileObject>d=new DiagnosticCollector<>();StandardJavaFileManager f=c.getStandardFileManager(d,null,null);JavacTask t=(JavacTask)c.getTask(null,f,d,Arrays.asList("-proc:none","-source","8","-classpath",new String(Files.readAllBytes(Paths.get(a[1]))).trim(),"-Xmaxerrs","100000"),null,f.getJavaFileObjectsFromStrings(Files.readAllLines(Paths.get(a[0]))));Trees tr=Trees.instance(t);List<CompilationUnitTree>us=new ArrayList<>();for(CompilationUnitTree u:t.parse())us.add(u);t.analyze();
 for(CompilationUnitTree u:us)new TreePathScanner<Void,Void>(){
 boolean sub(TypeMirror ty,String owner){TypeElement e=t.getElements().getTypeElement(owner);return ty!=null&&ty.getKind()==TypeKind.DECLARED&&e!=null&&t.getTypes().isSubtype(t.getTypes().erasure(ty),t.getTypes().erasure(e.asType()));}
 boolean legacy(TypeMirror ty,String name,int argc){if(ty==null||ty.getKind()!=TypeKind.DECLARED)return true;for(Element m:t.getElements().getAllMembers((TypeElement)t.getTypes().asElement(ty)))if(m instanceof ExecutableElement&&m.getSimpleName().contentEquals(name)&&((ExecutableElement)m).getParameters().size()==argc)return true;return false;}
 public Void visitMethod(MethodTree n,Void v){String name=n.getName().toString();if(name.equals("getUnlocalizedName")||name.equals("setUnlocalizedName")||name.equals("getTranslationKey")||name.equals("setTranslationKey")){Element e=tr.getElement(getCurrentPath());if(e instanceof ExecutableElement){Element owner=e.getEnclosingElement();System.err.println("DECL\t"+owner+"\t"+name+"\t"+n.getParameters().size()+"\t"+(sub(owner.asType(),"net.minecraft.item.Item")||sub(owner.asType(),"net.minecraft.block.Block")));}}return super.visitMethod(n,v);}
 public Void visitMethodInvocation(MethodInvocationTree n,Void v){ExpressionTree s=n.getMethodSelect();String name=s instanceof MemberSelectTree?((MemberSelectTree)s).getIdentifier().toString():s.toString();boolean setter=name.equals(a.length>2?"setTranslationKey":"setUnlocalizedName"),getter=name.equals(a.length>2?"getTranslationKey":"getUnlocalizedName");if(!setter&&!getter)return super.visitMethodInvocation(n,v);TypeMirror ty=null;ExpressionTree r=s instanceof MemberSelectTree?((MemberSelectTree)s).getExpression():null;TreePath sp=new TreePath(getCurrentPath(),s);
 if(r!=null)ty=tr.getTypeMirror(new TreePath(sp,r));else for(TreePath p=getCurrentPath();p!=null;p=p.getParentPath())if(p.getLeaf() instanceof ClassTree){Element e=tr.getElement(p);if(e instanceof TypeElement){ty=e.asType();break;}}
 String owner=sub(ty,"net.minecraft.item.Item")?"net.minecraft.item.Item":sub(ty,"net.minecraft.block.Block")?"net.minecraft.block.Block":"";boolean ok=!owner.isEmpty()&&!legacy(ty,setter?"setUnlocalizedName":"getUnlocalizedName",n.getArguments().size());String reason="owner/hierarchy"; if(a.length>2){Element e=tr.getElement(getCurrentPath());ok&=e instanceof ExecutableElement; if(e!=null)reason=e.getEnclosingElement().toString();}
 if(setter){ok&=owner.equals("net.minecraft.item.Item")&&!sub(ty,"net.minecraft.item.ItemBlock")&&n.getArguments().size()==1&&r instanceof NewClassTree&&((NewClassTree)r).getClassBody()==null; if(n.getArguments().size()==1){TypeMirror arg=tr.getTypeMirror(new TreePath(getCurrentPath(),n.getArguments().get(0)));ok&=arg!=null&&(arg.toString().equals("java.lang.String")||arg.getKind()==TypeKind.NULL);}reason="constructor-exact/no-legacy-override";}else{ok&=n.getArguments().isEmpty();reason="zero-argument/no-legacy-override";}
 long end=tr.getSourcePositions().getEndPosition(u,s),start=end-name.length();System.out.println((ok?"YES":"NO")+"\t"+Paths.get(u.getSourceFile().toUri())+"\t"+start+"\t"+end+"\t"+name+"\t"+(setter?"setTranslationKey":"getTranslationKey")+"\t"+ty+"\t"+owner+"\t"+reason+"\t"+(tr.getElement(getCurrentPath()) instanceof ExecutableElement?tr.getElement(getCurrentPath()).getEnclosingElement():"unresolved"));return super.visitMethodInvocation(n,v);}
 }.scan(u,null);System.err.println("Attribution diagnostics, not compile success: "+d.getDiagnostics().stream().filter(x->x.getKind()==Diagnostic.Kind.ERROR).count());
 }
}
